pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    assert!(!a.is_empty(), "input list must be non-empty");

    a.into_iter()
        .map(|s| {
            // Ensure each produced inner list is non-empty.
            if s.is_empty() {
                return vec![String::new()];
            }

            // Split on '\n'. If keepends is true, retain the '\n' on each line except
            // possibly the last if the string doesn't end with '\n'.
            let mut parts: Vec<Vec<char>> = Vec::new();
            let mut cur: Vec<char> = Vec::new();

            for ch in s.chars() {
                if ch == '\n' {
                    if keepends {
                        cur.push('\n');
                    }
                    parts.push(cur);
                    cur = Vec::new();
                } else {
                    cur.push(ch);
                }
            }
            parts.push(cur);

            // Convert to Strings; ensure non-empty inner list (it will be, since parts has >= 1).
            parts
                .into_iter()
                .map(|chars| chars.into_iter().collect::<String>())
                .collect::<Vec<String>>()
        })
        .collect()
}